<template>
  <div class="employment-hub">
    <header class="hub-hero">
      <div class="hero-copy"><div class="hub-eyebrow"><el-icon><Connection /></el-icon> 辅导员就业工作台</div><h1>就业与招考信息中心</h1><p>汇集招考与招聘信息，让适合本院研究生的机会更容易被发现。</p></div>
      <div class="hero-actions"><el-button @click="$router.push('/employment')"><el-icon><DataAnalysis /></el-icon>就业统计</el-button><el-button @click="openSources"><el-icon><Connection /></el-icon>信息来源</el-button><el-button v-if="canManage" type="primary" :loading="syncSubmitting" :disabled="syncState.running" @click="runSync()"><el-icon><Refresh /></el-icon>{{ syncState.running ? '正在同步' : '同步信息' }}</el-button></div>
    </header>

    <el-alert v-if="pageError" :title="pageError" type="error" :closable="false" show-icon class="hub-alert"><template #default><el-button text @click="loadWorkspace">重新连接</el-button></template></el-alert>
    <div class="hub-stats" aria-label="信息中心统计">
      <div v-for="stat in statTiles" :key="stat.key" class="hub-stat"><span class="stat-symbol" :class="stat.tone"><el-icon :size="21"><component :is="stat.icon" /></el-icon></span><div><span class="stat-caption">{{ stat.label }}</span><strong>{{ stat.value }}</strong></div><span class="stat-unit">条</span></div>
    </div>
    <div class="sync-strip" role="status" aria-live="polite"><span class="sync-dot" :class="{ live: schedulerRunning }" /><span>{{ schedulerLabel }}</span><span class="strip-divider">·</span><span>已接入 {{ connectedSources }} / {{ sources.length }} 个来源</span><span v-if="syncState.running" class="sync-progress">正在更新，完成后自动刷新</span><el-button link type="primary" @click="openSources">查看覆盖情况 <el-icon><ArrowRight /></el-icon></el-button></div>

    <div class="hub-layout">
      <main class="hub-main">
        <div class="hub-tabs" role="tablist" aria-label="就业信息类型"><button v-for="tab in tabs" :key="tab.key" type="button" role="tab" :aria-selected="activeTab === tab.key" :class="{ active: activeTab === tab.key }" @click="switchTab(tab.key)"><el-icon><component :is="tab.icon" /></el-icon>{{ tab.label }}</button></div>
        <section v-if="activeTab === 'company'" class="company-navigation" aria-label="企业招聘分组">
          <div class="company-track"><button v-for="track in companyTracks" :key="track.value" :class="{ active: filters.companyTrack === track.value }" :aria-pressed="filters.companyTrack === track.value" @click="filters.companyTrack = track.value; filters.employerType = ''; applyFilters()">{{ track.label }}</button></div>
          <p>汇集企业官网职位与公开招聘公告，点击详情查看条件和投递入口。</p>
        </section>
        <section class="hub-filters" aria-label="筛选信息">
          <div class="search-line"><el-input v-model="filters.q" clearable placeholder="搜索公告、岗位或单位名称" aria-label="搜索公告、岗位或单位名称" @keyup.enter="applyFilters"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-button type="primary" @click="applyFilters">搜索</el-button><el-button v-if="canManage" @click="openCreate"><el-icon><Plus /></el-icon>补充信息</el-button></div>
          <div class="filter-grid">
            <el-select v-model="filters.province" clearable filterable placeholder="全部地区" aria-label="地区筛选" @change="applyFilters"><el-option v-for="v in options.provinces" :key="v" :label="v" :value="v" /></el-select>
            <el-select v-model="filters.major" clearable placeholder="全部专业" aria-label="专业筛选" @change="applyFilters"><el-option v-for="v in options.majors" :key="v" :label="v" :value="v" /></el-select>
            <el-select v-if="activeTab !== 'company'" v-model="filters.category" clearable placeholder="全部信息类型" aria-label="类型筛选" @change="applyFilters"><el-option v-for="v in options.categories.filter(v => activeTab !== 'exam' || v !== '企业招聘')" :key="v" :label="v" :value="v" /></el-select>
            <el-select v-else v-model="filters.employerType" clearable placeholder="全部单位性质" aria-label="单位性质筛选" @change="applyFilters"><el-option v-for="v in options.employerTypes.filter(v => v !== '不适用')" :key="v" :label="v" :value="v" /></el-select>
            <el-select v-model="filters.status" clearable placeholder="全部报名状态" aria-label="报名状态筛选" @change="applyFilters"><el-option v-for="v in options.statuses" :key="v" :label="v" :value="v" /></el-select>
          </div>
          <div class="source-filter"><el-select v-model="filters.sourceId" clearable placeholder="全部信息来源" aria-label="信息来源筛选" @change="applyFilters"><el-option v-for="source in sources.filter(s => s.enabled || s.lastSuccess)" :key="source.id" :label="source.name" :value="source.id" /></el-select><span>官网职位、招聘公告、公告索引分别标识，保留原文入口。</span></div>
          <div class="filter-footer"><el-checkbox v-model="filters.saved" @change="applyFilters">只看我的收藏</el-checkbox><span v-if="filters.major" class="filter-note">专业关联用于发现机会，报考资格请核对公告原文。</span><el-button text size="small" @click="resetFilters">重置筛选</el-button></div>
        </section>

        <template v-if="activeTab === 'calendar'">
          <section class="hub-calendar" v-loading="calendarLoading">
            <div class="result-toolbar"><div><h2>报名与考试日历</h2><span>{{ events.length }} 个已明确时间的节点 · 北京时间</span></div><el-date-picker v-model="calendarMonth" type="month" value-format="YYYY-MM" :clearable="false" aria-label="日历月份" @change="() => loadCalendar()" /></div>
            <el-alert v-if="calendarError" :title="calendarError" type="error" :closable="false"><template #default><el-button text @click="loadCalendar">重试</el-button></template></el-alert>
            <el-alert v-if="calendarTruncated" title="本月结果超过 1000 条，仅展示前 1000 条，请按地区或专业缩小范围。" type="warning" :closable="false" show-icon />
            <div class="calendar-week"><span v-for="d in ['一','二','三','四','五','六','日']" :key="d">周{{ d }}</span></div>
            <div class="calendar-grid"><button v-for="cell in calendarCells" :key="cell.key" type="button" class="calendar-day" :class="{ empty: !cell.date, selected: selectedDate === cell.date, today: cell.date === today }" :disabled="!cell.date" :aria-label="cell.date ? `${cell.date}，${eventsForDate(cell.date).length}个节点` : '空白日期'" @click="selectedDate = cell.date"><span class="day-number">{{ cell.day }}</span><span v-for="event in eventsForDate(cell.date).slice(0,2)" :key="event.key" class="calendar-chip" :class="event.kind">{{ event.label }} · {{ event.item.title }}</span><span v-if="eventsForDate(cell.date).length > 2" class="calendar-more">另 {{ eventsForDate(cell.date).length - 2 }} 项</span></button></div>
            <div class="calendar-legend"><span><i class="legend-dot start" />报名开始</span><span><i class="legend-dot end" />报名截止</span><span><i class="legend-dot exam" />考试</span><span>没有明确日期的信息不会生成日历节点</span></div>
            <div class="calendar-detail"><div class="minor-heading"><h3>{{ selectedDate || '本月' }}的节点</h3><el-button v-if="selectedDate" text size="small" @click="selectedDate = ''">显示整月</el-button></div><button v-for="event in selectedEvents" :key="event.key" type="button" class="event-row" @click="showDetail(event.item)"><span class="event-date">{{ formatTime(event.time, true) }}</span><el-tag size="small" :type="event.kind === 'end' ? 'warning' : event.kind === 'exam' ? 'info' : 'success'">{{ event.label }}</el-tag><span class="event-title">{{ event.item.title }}</span><el-icon><ArrowRight /></el-icon></button><p v-if="!selectedEvents.length" class="quiet-empty">{{ selectedDate ? '这一天暂无已核实时间的节点。' : '本月暂无明确时间的节点；可查看信息列表中的原文，或补充报名时间。' }}</p></div>
          </section>
        </template>
        <template v-else>
          <div class="result-toolbar"><div><h2>{{ currentTab.label }}</h2><span>{{ count }} 条信息{{ activeTab === 'featured' ? ' · 老师核选的重点机会' : ' · 按发布时间更新' }}</span></div><el-radio-group v-model="viewMode" size="small" aria-label="展示方式"><el-radio-button label="cards"><el-icon><Grid /></el-icon> 卡片</el-radio-button><el-radio-button label="table"><el-icon><List /></el-icon> 列表</el-radio-button></el-radio-group></div>
          <div v-if="selectedIds.length" class="digest-toolbar"><span><el-icon><Document /></el-icon>已选 {{ selectedIds.length }} 条</span><div><el-button size="small" :loading="digestBusy" @click="buildDigest('copy')"><el-icon><CopyDocument /></el-icon>复制转发摘要</el-button><el-button size="small" :loading="digestBusy" @click="buildDigest('download')"><el-icon><Download /></el-icon>导出摘要</el-button><el-button text size="small" @click="selectedIds = []">清空</el-button></div></div>
          <el-alert v-if="listError" :title="listError" type="error" :closable="false" show-icon class="hub-alert"><template #default><el-button text @click="loadItems">重试</el-button></template></el-alert>
          <div v-if="loading && !items.length" class="list-skeleton"><el-skeleton :rows="7" animated /></div>
          <div v-else-if="!listError && !items.length" class="hub-empty"><span class="empty-symbol"><el-icon :size="35"><component :is="activeTab === 'company' ? Briefcase : Document" /></el-icon></span><h3>{{ activeTab === 'featured' ? '还没有老师精选' : '暂时没有符合条件的信息' }}</h3><p>{{ activeTab === 'featured' ? '打开信息详情，将值得关注的机会加入老师精选。' : '可调整筛选条件，或查看已接入的来源与同步状态。' }}</p><div><el-button @click="openSources">查看信息来源</el-button><el-button v-if="canManage" type="primary" @click="openCreate">补充真实信息</el-button></div></div>
          <div v-else-if="viewMode === 'cards'" v-loading="loading" class="opportunity-cards">
            <article v-for="item in items" :key="item.id" class="opportunity-card" :class="{ picked: selectedIds.includes(item.id) }">
              <div class="card-top"><span class="category-label" :class="{ corporate: item.category === '企业招聘' }"><el-icon><component :is="item.category === '企业招聘' ? Briefcase : Document" /></el-icon>{{ item.category === '企业招聘' ? entryLabel(item) : item.category }}<span v-if="item.category === '企业招聘'"> · {{ item.employerType }}</span></span><div class="card-top-right"><span v-if="item.featured" class="featured-mark"><el-icon><StarFilled /></el-icon>老师精选</span><el-button text circle :loading="busyIds.includes(item.id)" :aria-label="item.saved ? '取消收藏' : '收藏信息'" @click="toggleSaved(item)"><el-icon :class="{ 'saved-star': item.saved }"><component :is="item.saved ? StarFilled : Star" /></el-icon></el-button></div></div>
              <button type="button" class="opportunity-title" @click="showDetail(item)">{{ item.title }}</button>
              <div class="opportunity-meta"><span><el-icon><Location /></el-icon>{{ item.metadata?.locationText || item.province || '地区待核实' }}</span><span v-if="item.employer"><el-icon><OfficeBuilding /></el-icon>{{ item.employer }}</span><span v-if="item.publishedAt">发布 {{ formatTime(item.publishedAt) }}</span><span v-else-if="item.metadata?.sourceUpdatedAt">官网更新 {{ formatTime(item.metadata.sourceUpdatedAt) }}</span></div>
              <p class="opportunity-summary">{{ item.summary || '打开公告原文查看招聘要求及岗位说明。' }}</p>
              <div class="major-line"><span class="match-label">{{ item.matchKind || '待核实' }}</span><span>{{ item.relatedMajors?.length ? item.relatedMajors.join('、') : '专业条件待核对' }}</span></div>
              <div class="card-deadline"><el-tag :type="statusType(item.status)" size="small">{{ item.status || '时间待核实' }}</el-tag><span><el-icon><Clock /></el-icon>{{ deadlineLabel(item) }}</span><span v-if="item.reviewState === '待核对'" class="review-note">待核对</span></div>
              <div class="card-footer"><span class="source-caption" :title="item.sourceName">{{ item.sourceName || '人工补充' }}</span><el-checkbox :model-value="selectedIds.includes(item.id)" :aria-label="`选取摘要：${item.title}`" @change="value => selectItem(item.id, value)">选取摘要</el-checkbox><el-button link type="primary" @click="showDetail(item)">查看详情<el-icon><ArrowRight /></el-icon></el-button></div>
            </article>
          </div>
          <el-table v-else v-loading="loading" :data="items" class="hub-table" row-key="id" @row-dblclick="showDetail">
            <el-table-column label="选取" width="55"><template #default="{ row }"><el-checkbox :model-value="selectedIds.includes(row.id)" :aria-label="`选取摘要：${row.title}`" @change="value => selectItem(row.id, value)" /></template></el-table-column><el-table-column label="公告 / 岗位" min-width="270"><template #default="{ row }"><el-button link type="primary" class="table-title" @click="showDetail(row)">{{ row.title }}</el-button><div class="table-caption">{{ row.sourceName || '人工补充' }}</div></template></el-table-column><el-table-column prop="category" label="类型" width="95" /><el-table-column prop="province" label="地区" width="90" /><el-table-column label="状态" width="115"><template #default="{ row }"><el-tag size="small" :type="statusType(row.status)">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="截止时间" width="170"><template #default="{ row }">{{ formatTime(row.registrationEnd, true) }}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{ row }"><el-button link type="primary" @click="toggleSaved(row)">{{ row.saved ? '已收藏' : '收藏' }}</el-button></template></el-table-column>
          </el-table>
          <el-pagination v-if="count > 0" v-model:current-page="page" v-model:page-size="pageSize" :total="count" :page-sizes="[12,24,48]" layout="total, prev, pager, next, sizes" class="hub-pagination" @current-change="loadItems" @size-change="applyFilters" />
        </template>
      </main>

      <aside class="hub-aside">
        <section class="aside-panel deadline-panel"><div class="aside-heading"><span class="aside-icon amber"><el-icon><AlarmClock /></el-icon></span><h2>即将截止</h2><span class="small-label">未来 3 天</span></div><template v-if="closingItems.length"><button v-for="item in closingItems" :key="item.id" type="button" class="deadline-item" @click="showDetail(item)"><span class="deadline-counter">{{ item.daysLeft ?? '—' }}<small>天</small></span><span><strong>{{ item.title }}</strong><small>{{ formatTime(item.registrationEnd, true) }}</small></span></button></template><p v-else class="aside-empty">{{ deadlineError || '暂无已明确时间且即将截止的信息。' }}</p><el-button v-if="deadlineError" text @click="loadDeadlines">重试</el-button></section>
        <section class="aside-panel"><div class="aside-heading"><span class="aside-icon teal"><el-icon><Connection /></el-icon></span><h2>来源覆盖</h2></div><div class="coverage-number"><strong>{{ connectedSources }}</strong><span>/ {{ sources.length }} 个来源已接入</span></div><div class="coverage-track"><span :style="{ width: sources.length ? `${connectedSources / sources.length * 100}%` : '0%' }" /></div><div v-for="source in sources.slice(0,4)" :key="source.id" class="source-mini"><span>{{ source.name }}</span><span :class="{ 'source-error': source.status === 'error' }">{{ sourceLabel(source) }}</span></div><el-button link type="primary" @click="openSources">查看来源与最近更新时间<el-icon><ArrowRight /></el-icon></el-button></section>
        <section class="aside-panel workflow-panel"><div class="aside-heading"><span class="aside-icon blue"><el-icon><CopyDocument /></el-icon></span><h2>整理转发</h2></div><ol><li><span>1</span><div><strong>找到相关机会</strong><small>按地区、专业与报名状态筛选</small></div></li><li><span>2</span><div><strong>核对官方原文</strong><small>确认岗位条件、附件与关键时间</small></div></li><li><span>3</span><div><strong>勾选并复制摘要</strong><small>保留原文链接，便于老师转发</small></div></li></ol></section>
      </aside>
    </div>
    <footer class="hub-scope"><el-icon><InfoFilled /></el-icon>所有日期按北京时间展示。专业关联用于信息筛选，最终报考资格及时间以发布单位最新公告为准。</footer>

    <el-drawer v-model="detailVisible" title="信息详情" :size="drawerSize" class="hub-detail-drawer">
      <div v-loading="detailLoading" class="hub-detail"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"><template #default><el-button text @click="showDetail(detail)">重试</el-button></template></el-alert><template v-if="detail"><div class="detail-badges"><el-tag>{{ detail.category === '企业招聘' ? entryLabel(detail) : detail.category }}</el-tag><el-tag v-if="detail.category === '企业招聘'" type="info">{{ detail.employerType }}</el-tag><el-tag :type="statusType(detail.status)">{{ detail.status }}</el-tag><el-tag :type="detail.reviewState === '已核对' ? 'success' : 'warning'">{{ detail.reviewState }}</el-tag></div><h2 class="detail-title">{{ detail.title }}</h2><div class="detail-caption">{{ detail.metadata?.locationText || detail.province }}<span v-if="detail.employer"> · {{ detail.employer }}</span></div><div class="detail-actions"><el-button type="primary" :disabled="!safeUrl(detail.url)" @click="openUrl(detail.url)"><el-icon><Link /></el-icon>查看原文</el-button><el-button v-if="safeUrl(detail.metadata?.applyUrl)" type="primary" plain @click="openUrl(detail.metadata.applyUrl)">公告投递入口 <el-icon><TopRight /></el-icon></el-button><el-button :loading="busyIds.includes(detail.id)" @click="toggleSaved(detail)"><el-icon><component :is="detail.saved ? StarFilled : Star" /></el-icon>{{ detail.saved ? '已收藏' : '收藏' }}</el-button><el-button v-if="canManage" @click="toggleFeatured(detail)">{{ detail.featured ? '取消精选' : '加入老师精选' }}</el-button><el-button v-if="canManage" @click="openEdit(detail)"><el-icon><Edit /></el-icon>核对 / 更正</el-button></div><section class="detail-section"><h3>关键时间</h3><dl class="detail-times"><div><dt>报名开始</dt><dd>{{ formatTime(detail.registrationStart, true) }}</dd></div><div><dt>报名截止</dt><dd>{{ formatTime(detail.registrationEnd, true) }}</dd></div><div><dt>考试时间</dt><dd>{{ formatTime(detail.examAt, true) }}</dd></div></dl></section><section class="detail-section"><h3>信息摘要</h3><p class="preserve-text">{{ detail.summary || '暂无摘要，请查看原文。' }}</p></section><section class="detail-section"><h3>专业关联依据 <el-tag size="small" type="info">{{ detail.matchKind }}</el-tag></h3><div class="detail-majors"><el-tag v-for="major in detail.relatedMajors" :key="major" size="small" effect="plain">{{ major }}</el-tag><span v-if="!detail.relatedMajors?.length">专业条件待核实</span></div><ul v-if="detail.matchReasons?.length" class="detail-reasons"><li v-for="(reason,index) in detail.matchReasons" :key="index">{{ typeof reason === 'string' ? reason : JSON.stringify(reason) }}</li></ul><p class="verification-note">关联方向不等于资格符合。请核对专业代码、学历学位、毕业届别及公告规定的其他条件。</p></section><section class="detail-section"><h3>招聘 / 报考要求</h3><p class="preserve-text">{{ detail.requirements || '尚未提取完整条件，请以原文及岗位附件为准。' }}</p></section><section v-if="detail.attachments?.length" class="detail-section"><h3>公告附件</h3><a v-for="(attachment,index) in detail.attachments" :key="index" :href="safeUrl(attachment.url) || undefined" target="_blank" rel="noopener noreferrer" class="attachment-link"><el-icon><Document /></el-icon>{{ attachment.name || '查看附件' }}</a></section><section class="detail-section detail-provenance"><h3>来源与核验</h3><dl><div><dt>信息来源</dt><dd>{{ detail.sourceName || '人工补充' }}</dd></div><div><dt>发布时间</dt><dd>{{ formatTime(detail.publishedAt) }}</dd></div><div v-if="detail.metadata?.sourceUpdatedAt"><dt>官网更新时间</dt><dd>{{ formatTime(detail.metadata.sourceUpdatedAt, true) }}</dd></div><div><dt>最近获取</dt><dd>{{ formatTime(detail.lastSeen, true) }}</dd></div><div><dt>记录更新</dt><dd>{{ formatTime(detail.updatedAt, true) }}</dd></div></dl><a v-if="safeUrl(detail.url)" :href="safeUrl(detail.url)" target="_blank" rel="noopener noreferrer">{{ detail.url }}</a></section><section v-if="detail.revisions?.length" class="detail-section"><h3>变更记录</h3><div v-for="(revision,index) in detail.revisions" :key="index" class="revision-row"><span>{{ formatTime(revision.at || revision.updatedAt || revision.changedAt, true) }}</span><p>{{ revisionSummary(revision) }}</p></div></section></template></div>
    </el-drawer>

    <el-dialog v-model="sourcesVisible" title="信息来源与同步状态" width="min(980px, 96vw)">
      <div class="source-dialog-head"><div><p>{{ schedulerLabel }}</p><p class="small-label">仅已接入且启用的来源参与自动同步；官方入口和待接入来源不计作已采集。</p></div><el-button v-if="canManage" type="primary" :disabled="syncState.running" :loading="syncSubmitting" @click="runSync()">同步已启用来源</el-button></div>
      <el-alert v-if="sourceError" :title="sourceError" type="error" :closable="false"><template #default><el-button text @click="loadSources">重试</el-button></template></el-alert>
      <el-table v-loading="sourcesLoading" :data="sources" max-height="480" empty-text="尚未配置来源"><el-table-column label="来源" min-width="225"><template #default="{ row }"><a :href="safeUrl(row.url) || undefined" target="_blank" rel="noopener noreferrer" class="source-link">{{ row.name }} <el-icon><TopRight /></el-icon></a><div class="table-caption">{{ row.province }} · {{ row.category || '综合信息' }}</div></template></el-table-column><el-table-column label="接入状态" width="115"><template #default="{ row }"><el-tag :type="row.status === 'error' ? 'danger' : row.status === 'success' && row.enabled ? 'success' : 'info'" size="small">{{ sourceLabel(row) }}</el-tag></template></el-table-column><el-table-column label="最近成功同步" width="165"><template #default="{ row }">{{ row.lastSuccess ? formatTime(row.lastSuccess, true) : '尚未成功同步' }}</template></el-table-column><el-table-column label="说明" min-width="220"><template #default="{ row }"><div class="source-coverage">{{ row.metadata?.coverage || row.metadata?.note || row.metadata?.description || (row.enabled ? '按配置周期检查公开信息' : '可访问来源原网站查看信息') }}</div><div v-if="row.metadata?.reason" class="source-reason">{{ row.metadata.reason }}</div><div v-if="row.lastError" class="source-error">{{ row.lastError }}</div><div v-if="row.metadata?.lastResult" class="source-result">最近一次：检查 {{ row.metadata.lastResult.checked || 0 }} · 新增 {{ row.metadata.lastResult.created || 0 }} · 更新 {{ row.metadata.lastResult.updated || 0 }}<span v-if="row.metadata.detailErrors"> · {{ row.metadata.detailErrors }} 条详情待重试</span></div></template></el-table-column><el-table-column v-if="canManage" label="操作" width="85"><template #default="{ row }"><el-button link type="primary" :disabled="!row.enabled || syncState.running" @click="runSync(row.id)">同步</el-button></template></el-table-column></el-table>
      <div v-if="latestRun" class="latest-run"><strong>最近同步任务</strong><span>{{ runLabel(latestRun.status) }} · {{ formatTime(latestRun.startedAt || latestRun.createdAt, true) }}</span><span v-if="latestRun.createdCount !== undefined">新增 {{ latestRun.createdCount }} · 更新 {{ latestRun.updatedCount || 0 }} · 检查 {{ latestRun.checkedCount || 0 }}</span><span v-if="latestRun.error" class="source-error">{{ latestRun.error }}</span></div>
      <template #footer><el-button @click="sourcesVisible = false">关闭</el-button></template>
    </el-dialog>

    <el-dialog v-model="formVisible" :title="editingId ? '核对与更正信息' : '补充就业 / 招考信息'" width="min(800px, 96vw)" :close-on-click-modal="false">
      <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="hub-alert" />
      <el-form :model="form" label-position="top" @submit.prevent="submitForm">
        <el-form-item label="公告 / 岗位标题" required><el-input v-model="form.title" maxlength="300" placeholder="填写原公告标题" /></el-form-item><el-form-item label="官方公告链接" required><el-input v-model="form.url" placeholder="https://…" /></el-form-item>
        <div class="form-grid"><el-form-item label="信息类型" required><el-select v-model="form.category"><el-option v-for="v in options.categories" :key="v" :value="v" :label="v" /></el-select></el-form-item><el-form-item label="地区" required><el-select v-model="form.province" filterable><el-option v-for="v in options.provinces" :key="v" :value="v" :label="v" /></el-select></el-form-item><el-form-item label="招聘单位"><el-input v-model="form.employer" maxlength="200" /></el-form-item><el-form-item v-if="form.category === '企业招聘'" label="单位性质"><el-select v-model="form.employerType"><el-option v-for="v in options.employerTypes.filter(v => v !== '不适用')" :key="v" :label="v" :value="v" /></el-select></el-form-item><el-form-item label="发布日期"><input v-model="form.publishedAt" type="date" class="native-input" aria-label="发布日期" /></el-form-item></div>
        <div class="form-grid"><el-form-item label="报名开始（北京时间）"><input v-model="form.registrationStart" type="datetime-local" class="native-input" aria-label="报名开始（北京时间）" /></el-form-item><el-form-item label="报名截止（北京时间）"><input v-model="form.registrationEnd" type="datetime-local" class="native-input" aria-label="报名截止（北京时间）" /></el-form-item><el-form-item label="考试时间（北京时间）"><input v-model="form.examAt" type="datetime-local" class="native-input" aria-label="考试时间（北京时间）" /></el-form-item></div>
        <el-form-item label="关联专业"><el-select v-model="form.relatedMajors" multiple placeholder="选择专业；无法确认时留空"><el-option v-for="v in options.majors" :key="v" :value="v" :label="v" /></el-select></el-form-item><div class="form-grid"><el-form-item label="专业关联方式"><el-select v-model="form.matchKind"><el-option v-for="v in ['明确提及','方向相关','不限专业','待核实']" :key="v" :label="v" :value="v" /></el-select></el-form-item><el-form-item label="人工核对状态"><el-select v-model="form.reviewState"><el-option label="待核对" value="待核对" /><el-option label="已核对" value="已核对" /></el-select></el-form-item></div>
        <el-form-item label="专业关联依据（每行一项）"><el-input v-model="form.matchReasonsText" type="textarea" :rows="2" placeholder="填写原文中明确的专业要求或关联方向" /></el-form-item><el-form-item label="信息摘要"><el-input v-model="form.summary" type="textarea" :rows="3" maxlength="5000" show-word-limit /></el-form-item><el-form-item label="招聘 / 报考条件原文"><el-input v-model="form.requirements" type="textarea" :rows="4" maxlength="20000" /></el-form-item>
        <p class="verification-note">未明确的日期和资格条件请留空；“已核对”表示老师已检查信息，不代表学生一定符合报考条件。</p>
      </el-form><template #footer><el-button :disabled="formSaving" @click="formVisible = false">取消</el-button><el-button type="primary" :loading="formSaving" @click="submitForm">保存到信息库</el-button></template>
    </el-dialog>
    <el-dialog v-model="digestVisible" title="转发摘要" width="min(720px, 95vw)"><p class="digest-hint">可选中下方文字复制；摘要保留官方原文链接。</p><el-input v-model="digestText" type="textarea" :rows="16" readonly aria-label="转发摘要内容" /><template #footer><el-button @click="downloadText(digestText)">导出文本</el-button><el-button type="primary" @click="copyDigest">复制摘要</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { AlarmClock, ArrowRight, Briefcase, Calendar, Clock, Collection, Connection, CopyDocument, DataAnalysis, Document, Download, Edit, Grid, InfoFilled, Link, List, Location, OfficeBuilding, Plus, Refresh, Search, Star, StarFilled, TopRight } from '@element-plus/icons-vue'
import { REAL_MAJORS } from '../utils/graduateCatalog'
import { calendarEvents, formatEmploymentTime, manualOpportunityPayload, monthDays, recruitmentEntryLabel, safeEmploymentUrl, shanghaiDate, sourceStatusLabel } from '../utils/employmentHub'
import { createOpportunity, featureOpportunity, getEmploymentCalendar, getEmploymentDigest, getEmploymentMeta, getEmploymentSources, getEmploymentSync, getOpportunities, getOpportunity, saveOpportunity, syncEmploymentSources, updateOpportunity } from '../services/employmentService'

const tabs = [{ key: 'exam', label: '招考公告', icon: Document }, { key: 'company', label: '企业岗位', icon: Briefcase }, { key: 'calendar', label: '报名日历', icon: Calendar }, { key: 'featured', label: '老师精选', icon: StarFilled }]
const activeTab = ref('exam'), viewMode = ref('cards'), page = ref(1), pageSize = ref(12)
const items = ref([]), count = ref(0), meta = ref(null), sources = ref([]), syncState = ref({ items: [], running: false })
const loading = ref(false), pageError = ref(''), listError = ref(''), sourceError = ref(''), sourcesLoading = ref(false), sourcesVisible = ref(false), syncSubmitting = ref(false), syncError = ref('')
const filters = reactive({ q: '', category: '', province: '', major: '', employerType: '', companyTrack: '', sourceId: '', status: '', saved: false })
const appliedFilters = ref({ ...filters })
const selectedIds = ref([]), busyIds = ref([]), closingItems = ref([]), deadlineError = ref('')
const today = ref(shanghaiDate(new Date())), calendarMonth = ref(today.value.slice(0,7)), selectedDate = ref(''), calendarItems = ref([]), calendarLoading = ref(false), calendarError = ref(''), calendarTruncated = ref(false)
const detailVisible = ref(false), detail = ref(null), detailLoading = ref(false), detailError = ref('')
const formVisible = ref(false), formSaving = ref(false), formError = ref(''), editingId = ref(null)
const emptyForm = () => ({ title: '', url: '', category: '选调生', province: '', employer: '', employerType: '未说明', publishedAt: '', registrationStart: '', registrationEnd: '', examAt: '', relatedMajors: [], matchReasonsText: '', matchKind: '待核实', reviewState: '待核对', summary: '', requirements: '' })
const form = reactive(emptyForm()), digestBusy = ref(false), digestVisible = ref(false), digestText = ref('')
let listVersion = 0, calendarVersion = 0, detailVersion = 0, metaVersion = 0, sourceVersion = 0, deadlineVersion = 0, pollTimer, refreshTimer, pollBusy = false, refreshBusy = false, lastBusinessRefresh = 0, disposed = false
const currentTab = computed(() => tabs.find(t => t.key === activeTab.value))
const canManage = computed(() => Boolean(meta.value?.canManage))
const options = computed(() => ({ majors: REAL_MAJORS, provinces: [], categories: ['选调生','公务员','事业单位','人才引进','企业招聘'], employerTypes: ['央企','国企','民企','未说明','不适用'], statuses: ['报名中','即将截止','尚未开始','已截止','时间待核实'], ...meta.value?.filters }))
const statTiles = computed(() => [{ key: 'total', label: '信息库总量', icon: Collection, tone: 'blue' }, { key: 'addedToday', label: '今日新增', icon: Plus, tone: 'teal' }, { key: 'closingSoon', label: '即将截止', icon: AlarmClock, tone: 'amber' }, { key: 'featured', label: '老师精选', icon: StarFilled, tone: 'violet' }].map(v => ({ ...v, value: meta.value?.stats?.[v.key] ?? '—' })))
const connectedSources = computed(() => sources.value.filter(s => s.enabled && s.status === 'success').length)
const scheduler = computed(() => syncState.value.scheduler || meta.value?.scheduler || {})
const schedulerRunning = computed(() => !syncError.value && Boolean(scheduler.value.running || scheduler.value.active))
const schedulerLabel = computed(() => syncError.value ? '暂时无法读取同步状态，请检查后端连接' : schedulerRunning.value ? `自动同步运行中${scheduler.value.lastHeartbeat ? ` · 最近心跳 ${formatTime(scheduler.value.lastHeartbeat, true)}` : ''}` : '自动同步未运行 · 可手动同步或启动后台同步服务')
const latestRun = computed(() => syncState.value.items?.[0])
const events = computed(() => calendarEvents(calendarItems.value, calendarMonth.value))
const calendarCells = computed(() => monthDays(calendarMonth.value))
const selectedEvents = computed(() => selectedDate.value ? eventsForDate(selectedDate.value) : events.value)
const drawerSize = 'min(760px, 96vw)'
const entryLabel = recruitmentEntryLabel
const companyTracks = [{ value: '', label: '全部企业' }, { value: 'state', label: '央国企' }, { value: 'internet', label: '互联网科技' }]
const formatTime = formatEmploymentTime, safeUrl = safeEmploymentUrl, sourceLabel = sourceStatusLabel
const statusType = status => ({ 报名中: 'success', 即将截止: 'warning', 已截止: 'info', 尚未开始: 'primary', 时间待核实: 'info' }[status] || 'info')
const runLabel = status => ({ running: '同步中', queued: '等待同步', pending: '等待同步', success: '同步完成', completed: '同步完成', partial: '部分来源未完成', error: '同步失败', failed: '同步失败' }[status] || status || '待同步')
const eventsForDate = date => events.value.filter(event => event.date === date)
const query = (extras = {}) => ({ ...appliedFilters.value, channel: activeTab.value === 'exam' ? 'exam' : activeTab.value === 'company' ? 'company' : '', category: activeTab.value === 'company' ? '' : appliedFilters.value.category, employerType: activeTab.value === 'company' ? appliedFilters.value.employerType : '', companyTrack: activeTab.value === 'company' ? appliedFilters.value.companyTrack : '', featured: activeTab.value === 'featured' ? 1 : '', ...extras })
const deadlineLabel = item => item.registrationEnd ? `${item.daysLeft > 0 ? `${item.daysLeft} 天内截止 · ` : '截止 '}${formatTime(item.registrationEnd, true)}` : '报名时间待核实'

function revisionSummary(revision) {
  if (revision.summary || revision.reason || revision.title) return revision.summary || revision.reason || revision.title
  const labels = { title: '标题', category: '类型', province: '地区', employer_type: '单位性质', employer: '招聘单位', registration_start: '报名开始', registration_end: '报名截止', exam_at: '考试时间', related_majors: '关联专业', match_kind: '关联方式', review_state: '核对状态', summary: '摘要', requirements: '招聘条件', canonical_url: '原文链接', match_reasons: '关联依据' }
  return revision.changes ? Object.entries(revision.changes).map(([key, value]) => {
    if (value && typeof value === 'object' && 'after' in value) { const text = input => Array.isArray(input) ? input.join('、') : String(input ?? '未填写'); return `${labels[key] || key}：${text(value.before).slice(0,100)} → ${text(value.after).slice(0,100)}` }
    return labels[key] || key
  }).join('；') : '公告内容发生变更，请查看最新原文。'
}

async function loadItems() {
  const version = ++listVersion
  loading.value = true; listError.value = ''
  try { const result = await getOpportunities(query({ page: page.value, pageSize: pageSize.value })); if (version !== listVersion || disposed) return; items.value = result.items || []; count.value = result.count || 0; if (result.stats && meta.value) meta.value.stats = result.stats }
  catch (error) { if (version === listVersion && !disposed) { listError.value = error.message; items.value = []; count.value = 0 } }
  finally { if (version === listVersion && !disposed) loading.value = false }
}
async function loadMeta() { const version = ++metaVersion; const result = await getEmploymentMeta(); if (version === metaVersion && !disposed) { meta.value = result; pageError.value = '' } }
async function loadSources() {
  const version = ++sourceVersion
  sourcesLoading.value = true; sourceError.value = ''
  try { const result = await getEmploymentSources(); if (version === sourceVersion && !disposed) sources.value = Array.isArray(result) ? result : result.items || [] }
  catch (error) { if (version === sourceVersion && !disposed) sourceError.value = error.message }
  finally { if (version === sourceVersion && !disposed) sourcesLoading.value = false }
}
async function loadDeadlines() { const version = ++deadlineVersion; try { const result = await getOpportunities({ status: '即将截止', pageSize: 4 }); if (version === deadlineVersion && !disposed) { closingItems.value = result.items || []; deadlineError.value = '' } } catch (error) { if (version === deadlineVersion && !disposed) { closingItems.value = []; deadlineError.value = error.message } } }
async function loadWorkspace() { pageError.value = ''; const results = await Promise.allSettled([loadMeta(), loadItems(), loadSources(), loadDeadlines(), pollSync()]); if (disposed) return; lastBusinessRefresh = Date.now(); if (results[0].status === 'rejected') pageError.value = results[0].reason.message }
function applyFilters() { appliedFilters.value = { ...filters }; page.value = 1; activeTab.value === 'calendar' ? loadCalendar() : loadItems() }
function resetFilters() { Object.assign(filters, { q: '', category: '', province: '', major: '', employerType: '', companyTrack: '', sourceId: '', status: '', saved: false }); applyFilters() }
function switchTab(value) { if (activeTab.value === value) return; activeTab.value = value; filters.category = ''; appliedFilters.value = { ...filters }; page.value = 1; value === 'calendar' ? loadCalendar() : loadItems() }
async function loadCalendar(preserveSelection = false) {
  const version = ++calendarVersion; calendarLoading.value = true; calendarError.value = ''; if (!preserveSelection) selectedDate.value = ''
  try { const result = await getEmploymentCalendar(query({ month: calendarMonth.value })); if (version === calendarVersion && !disposed) { calendarItems.value = result.items || []; calendarTruncated.value = Boolean(result.truncated) } }
  catch (error) { if (version === calendarVersion && !disposed) { calendarError.value = error.message; calendarItems.value = [] } }
  finally { if (version === calendarVersion && !disposed) calendarLoading.value = false }
}
async function pollSync() {
  if (pollBusy || disposed || document.visibilityState === 'hidden') return
  pollBusy = true
  try { const wasRunning = syncState.value.running; const result = await getEmploymentSync(); if (disposed) return; syncState.value = result; syncError.value = ''; if (wasRunning && !result.running) { await Promise.allSettled([loadSources(), refreshBusiness()]) } }
  catch (error) { syncError.value = error.message; if (sourcesVisible.value) sourceError.value = error.message }
  finally { pollBusy = false }
}
async function runSync(sourceId) {
  syncSubmitting.value = true
  try { await syncEmploymentSources(sourceId); syncState.value.running = true; ElMessage.success('同步任务已启动，完成后会更新信息库'); await pollSync() }
  catch (error) { ElMessage.error(error.message) }
  finally { syncSubmitting.value = false }
}
function openSources() { sourcesVisible.value = true; loadSources(); pollSync() }
function selectItem(id, selected) { if (selected && !selectedIds.value.includes(id)) { if (selectedIds.value.length >= 30) return ElMessage.warning('一次最多整理 30 条信息'); selectedIds.value = [...selectedIds.value, id] } else if (!selected) selectedIds.value = selectedIds.value.filter(v => v !== id) }
function mergeItem(item) { for (const list of [items.value, closingItems.value, calendarItems.value]) { const index = list.findIndex(v => v.id === item.id); if (index >= 0) list.splice(index, 1, { ...list[index], ...item }) } if (detail.value?.id === item.id) { ++detailVersion; detailLoading.value = false; detail.value = { ...detail.value, ...item } } }
async function toggleSaved(item) { if (busyIds.value.includes(item.id)) return; busyIds.value.push(item.id); try { const result = await saveOpportunity(item.id, !item.saved); mergeItem({ ...item, ...result, saved: result.saved ?? !item.saved }); if (filters.saved && !detail.value?.saved) await loadItems() } catch (error) { ElMessage.error(error.message) } finally { busyIds.value = busyIds.value.filter(id => id !== item.id) } }
async function toggleFeatured(item) { if (busyIds.value.includes(item.id)) return; busyIds.value.push(item.id); try { const result = await featureOpportunity(item.id, !item.featured); mergeItem({ ...item, ...result, featured: result.featured ?? !item.featured }); await loadMeta(); if (activeTab.value === 'featured') await loadItems() } catch (error) { ElMessage.error(error.message) } finally { busyIds.value = busyIds.value.filter(id => id !== item.id) } }
async function showDetail(item) { if (!item?.id) return; const version = ++detailVersion; detail.value = item; detailVisible.value = true; detailLoading.value = true; detailError.value = ''; try { const result = await getOpportunity(item.id); if (version === detailVersion && !disposed) detail.value = result } catch (error) { if (version === detailVersion) detailError.value = error.message } finally { if (version === detailVersion) detailLoading.value = false } }
function openUrl(url) { const safe = safeUrl(url); if (safe) window.open(safe, '_blank', 'noopener,noreferrer') }
function openCreate() { editingId.value = null; Object.assign(form, emptyForm(), { category: activeTab.value === 'company' ? '企业招聘' : '选调生' }); formError.value = ''; formVisible.value = true }
function localInput(value) { if (!value) return ''; const date = new Date(value); if (!Number.isFinite(date.getTime())) return ''; const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(date); const p = key => parts.find(v => v.type === key)?.value; return `${p('year')}-${p('month')}-${p('day')}T${p('hour')}:${p('minute')}` }
function openEdit(item) { editingId.value = item.id; Object.assign(form, emptyForm(), Object.fromEntries(Object.keys(emptyForm()).map(key => [key, item[key] ?? emptyForm()[key]])), { relatedMajors: [...(item.relatedMajors || [])], matchReasonsText: (item.matchReasons || []).join('\n'), registrationStart: localInput(item.registrationStart), registrationEnd: localInput(item.registrationEnd), examAt: localInput(item.examAt), publishedAt: item.publishedAt || '' }); formError.value = ''; formVisible.value = true }
async function submitForm() {
  if (!form.title.trim() || !safeUrl(form.url) || !form.category || !form.province) { formError.value = '请填写标题、有效的 http/https 公告链接、信息类型和地区'; return }
  if (form.registrationStart && form.registrationEnd && form.registrationStart > form.registrationEnd) { formError.value = '报名截止时间不能早于报名开始时间'; return }
  formSaving.value = true; formError.value = ''
  try { const payload = manualOpportunityPayload(form); const result = editingId.value ? await updateOpportunity(editingId.value, payload) : await createOpportunity(payload); formVisible.value = false; ElMessage.success('信息已保存到数据库'); if (detail.value?.id === result.id) detail.value = result; await Promise.allSettled([loadMeta(), loadDeadlines(), activeTab.value === 'calendar' ? loadCalendar() : loadItems()]) }
  catch (error) { formError.value = error.message }
  finally { formSaving.value = false }
}
async function buildDigest(mode) { digestBusy.value = true; try { const result = await getEmploymentDigest(selectedIds.value); digestText.value = result.text; if (mode === 'download') downloadText(result.text); else await copyDigest() } catch (error) { ElMessage.error(error.message) } finally { digestBusy.value = false } }
async function copyDigest() { try { await navigator.clipboard.writeText(digestText.value); ElMessage.success('转发摘要已复制') } catch { digestVisible.value = true; ElMessage.info('请在摘要窗口中选中文字复制') } }
function downloadText(text) { const blob = new Blob(['\uFEFF', text], { type: 'text/plain;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `就业招考信息摘要-${shanghaiDate(new Date())}.txt`; document.body.appendChild(anchor); anchor.click(); anchor.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
async function refreshBusiness() {
  // Keep the current results stable while the teacher is editing or preparing a digest.
  if (disposed || refreshBusy || document.visibilityState === 'hidden' || formVisible.value || digestVisible.value || digestBusy.value || loading.value || calendarLoading.value || busyIds.value.length || filters.q !== appliedFilters.value.q) return
  refreshBusy = true; lastBusinessRefresh = Date.now(); today.value = shanghaiDate(new Date())
  const detailId = detailVisible.value && !detailLoading.value ? detail.value?.id : null
  const detailRequest = detailVersion
  try {
    const operations = [loadMeta(), loadDeadlines(), activeTab.value === 'calendar' ? loadCalendar(true) : loadItems()]
    if (detailId) operations.push(getOpportunity(detailId).then(result => { if (!disposed && !formVisible.value && detailVisible.value && detail.value?.id === detailId && detailVersion === detailRequest) detail.value = result }))
    const results = await Promise.allSettled(operations)
    if (!disposed && results[0].status === 'rejected') pageError.value = results[0].reason.message
  } finally { refreshBusy = false }
}
